import FileProvider
import StorageCollaboratorKit

final class FileProviderExtension: NSObject, NSFileProviderReplicatedExtension {
  private let domain:NSFileProviderDomain
  private let api:APIClient
  private let rootItemID:String
  required init(domain:NSFileProviderDomain){self.domain=domain;let defaults=UserDefaults(suiteName:"group.com.re8ch.storagecollaborator")!;let url=URL(string:defaults.string(forKey:"gatewayURL") ?? "https://storagecollaborator.invalid/")!;api=APIClient(configuration:.init(baseURL:url,token:defaults.string(forKey:"deviceToken") ?? ""));rootItemID=(defaults.dictionary(forKey:"workspaceRootItems") as? [String:String])?[domain.identifier.rawValue] ?? domain.identifier.rawValue;super.init()}
  func invalidate(){}
  func item(for identifier:NSFileProviderItemIdentifier,request:NSFileProviderRequest,completionHandler:@escaping(NSFileProviderItem?,Error?)->Void)->Progress{let p=Progress(totalUnitCount:1);Task{do{let remoteID = identifier == .rootContainer ? rootItemID : identifier.rawValue;completionHandler(StorageCollaboratorItem(try await api.item(remoteID),systemIdentifier:identifier == .rootContainer ? .rootContainer:nil),nil);p.completedUnitCount=1}catch{completionHandler(nil,error)}};return p}
  func fetchContents(for itemIdentifier:NSFileProviderItemIdentifier,version:NSFileProviderItemVersion?,request:NSFileProviderRequest,completionHandler:@escaping(URL?,NSFileProviderItem?,Error?)->Void)->Progress{let p=Progress(totalUnitCount:1);Task{do{let i=try await api.item(itemIdentifier.rawValue);let u=FileManager.default.temporaryDirectory.appendingPathComponent(UUID().uuidString);try await api.download(i,to:u);p.completedUnitCount=1;completionHandler(u,StorageCollaboratorItem(i),nil)}catch{completionHandler(nil,nil,error)}};return p}
  func createItem(basedOn itemTemplate:NSFileProviderItem,fields:NSFileProviderItemFields,contents contentsURL:URL?,options:NSFileProviderCreateItemOptions,request:NSFileProviderRequest,completionHandler:@escaping(NSFileProviderItem?,NSFileProviderItemFields,Bool,Error?)->Void)->Progress{let p=Progress(totalUnitCount:1);Task{do{var i=try await api.create(name:itemTemplate.filename,kind:itemTemplate.contentType == .folder ? .folder:.file,parentID:itemTemplate.parentItemIdentifier.rawValue);if let contentsURL{i=try await api.upload(contentsURL,item:i)};p.completedUnitCount=1;completionHandler(StorageCollaboratorItem(i),[],false,nil)}catch{completionHandler(nil,[],false,error)}};return p}
  func modifyItem(_ item:NSFileProviderItem,baseVersion:NSFileProviderItemVersion,changedFields:NSFileProviderItemFields,contents newContents:URL?,options:NSFileProviderModifyItemOptions,request:NSFileProviderRequest,completionHandler:@escaping(NSFileProviderItem?,NSFileProviderItemFields,Bool,Error?)->Void)->Progress{let p=Progress(totalUnitCount:1);Task{do{var i=try await api.item(item.itemIdentifier.rawValue);if changedFields.contains(.filename)||changedFields.contains(.parentItemIdentifier){i=try await api.move(i,name:item.filename,parentID:item.parentItemIdentifier.rawValue)};if let newContents{i=try await api.upload(newContents,item:i)};p.completedUnitCount=1;completionHandler(StorageCollaboratorItem(i),[],false,nil)}catch{completionHandler(nil,changedFields,false,error)}};return p}
  func deleteItem(identifier:NSFileProviderItemIdentifier,baseVersion:NSFileProviderItemVersion,options:NSFileProviderDeleteItemOptions,request:NSFileProviderRequest,completionHandler:@escaping(Error?)->Void)->Progress{let p=Progress(totalUnitCount:1);Task{do{try await api.delete(try await api.item(identifier.rawValue));p.completedUnitCount=1;completionHandler(nil)}catch{completionHandler(error)}};return p}
  func enumerator(for containerItemIdentifier:NSFileProviderItemIdentifier,request:NSFileProviderRequest)throws->NSFileProviderEnumerator{StorageCollaboratorEnumerator(container:containerItemIdentifier == .rootContainer ? .init(rootItemID):containerItemIdentifier,api:api,workspaceID:domain.identifier.rawValue)}
}
